import { useState } from "react";
import Button from "../common/Button/Button";
import styles from "./AuthCard.module.scss";
import TextInput from "../common/Inputs/TextInput/TextInput";
import TextButton from "../common/TextButton/TextButton";

type AuthType = "login" | "signup";

interface FormData {
  fullName?: string;
  email: string;
  password: string;
  confirmPassword?: string;
}

interface FormErrors {
  fullName?: string;
  email?: string;
  password?: string;
  confirmPassword?: string;
}

const AuthCard = () => {
  const [authType, setAuthType] = useState<AuthType>("login");
  const [formData, setFormData] = useState<FormData>({
    fullName: "",
    email: "",
    password: "",
    confirmPassword: "",
  });
  const [errors, setErrors] = useState<FormErrors>({});
    const handleInputChange = (field: keyof FormData, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    // Clear error when user starts typing
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: "" }));
    }
  };
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
  };
  return (
    <div className={styles.authContainer}>
      {/* Auth Type Switch */}
      <div className={styles.authSwitchButtonBox}>
        <Button
          className={`${styles.btn} ${
            btnType === "login" ? styles.atciveBtn : ""
          }`}
          text={"Login"}
          onClick={() => setBtnType("login")}
        />
        <Button
          className={`${styles.btn} ${
            btnType === "signup" ? styles.atciveBtn : ""
          }`}
          text={"Signup"}
          onClick={() => setBtnType("signup")}
        />
      </div>

      <form onSubmit={handleSubmit} className={styles.authForm}>
        <div className={styles.inputsContainer}>
          {authType === "signup" && (
            <TextInput
              label="Full Name"
              type="text"
              placeholder="John Doe"
              value={formData.fullName}
              onChange={(e) => handleInputChange("fullName", e.target.value)}
              errorMessage={errors.fullName}
            />
          )}

          <TextInput
            label="Email Address"
            type="email"
            placeholder="you@example.com"
            value={formData.email}
            onChange={(e) => handleInputChange("email", e.target.value)}
            errorMessage={errors.email}
          />

          <TextInput
            label="Password"
            type="password"
            placeholder="Enter your password"
            value={formData.password}
            onChange={(e) => handleInputChange("password", e.target.value)}
            errorMessage={errors.password}
          />

          {authType === "signup" && (
            <TextInput
              label="Confirm Password"
              type="password"
              placeholder="Confirm your password"
              value={formData.confirmPassword}
              onChange={(e) =>
                handleInputChange("confirmPassword", e.target.value)
              }
              errorMessage={errors.confirmPassword}
            />
          )}
        </div>
      </form>
      {btnType === "login" ? (
        <>
          <div className={styles.inputsContainer}>
            <TextInput label="Email Address" placeholder="you@example.com" />
            <TextInput
              label="Password"
              type="password"
              placeholder="********"
            />
          </div>
          <div className={styles.TextButtonContainer}>
            <TextButton
              href="/forgot-password"
              className={styles.TextButton}
              variant="primary"
              size="sm"
            >
              Forgot Password?
            </TextButton>
          </div>

          <Button
            className={styles.signBtn}
            text={"Login"}
            onClick={() => {}}
          />
        </>
      ) : (
        <>
          <div className={styles.inputsContainer}>
            <TextInput
              label="Full Name"
              placeholder="Omran Abandeh"
              errorMessage=""
            />
            <TextInput label="Email Address" placeholder="you@example.com" />
            <TextInput
              label="Password"
              type="password"
              placeholder="********"
            />
            <TextInput
              label="Confirm Password"
              type="password"
              placeholder="********"
            />
          </div>
          <div className={styles.TextButtonContainer}>
            <TextButton
              href="/forgot-password"
              className={styles.TextButton}
              variant="primary"
              size="sm"
            >
              Forgot Password?
            </TextButton>
          </div>

          <Button
            className={styles.signBtn}
            text={"Login"}
            onClick={() => {}}
          />
        </>
      )}
    </div>
  );
};

export default AuthCard;
